
-- Help Buddy personality/expression foundation; mirrors migration 20261118210609.
ALTER TABLE public.assistant_personality_presets
 ADD COLUMN IF NOT EXISTS personality_group text NOT NULL DEFAULT 'legacy',
 ADD COLUMN IF NOT EXISTS default_intensity smallint NOT NULL DEFAULT 50 CHECK(default_intensity BETWEEN 0 AND 100),
 ADD COLUMN IF NOT EXISTS user_selectable boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS communication_profile jsonb NOT NULL DEFAULT '{}'::jsonb,
 ADD COLUMN IF NOT EXISTS behavior_traits jsonb NOT NULL DEFAULT '{}'::jsonb,
 ADD COLUMN IF NOT EXISTS is_canonical boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS is_legacy boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS public.help_buddy_expression_catalog(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),expression_key text NOT NULL UNIQUE,category_key text NOT NULL,
 category_name text NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',
 emotion_tags text[] NOT NULL DEFAULT '{}',visual_spec jsonb NOT NULL DEFAULT '{}'::jsonb,
 asset_storage_path text,thumbnail_storage_path text,animation_storage_path text,
 animation_manifest jsonb NOT NULL DEFAULT '{}'::jsonb,
 asset_status text NOT NULL DEFAULT 'awaiting_artwork' CHECK(asset_status IN('awaiting_artwork','uploaded','in_review','approved','rejected')),
 status text NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','retired')),
 sort_order integer NOT NULL DEFAULT 100,version integer NOT NULL DEFAULT 1,
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.help_buddy_behavior_rules(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_key text NOT NULL UNIQUE,name text NOT NULL,
 description text NOT NULL DEFAULT '',trigger_categories text[] NOT NULL DEFAULT '{}',
 severity_level smallint NOT NULL DEFAULT 1 CHECK(severity_level BETWEEN 1 AND 5),
 personality_keys text[] NOT NULL DEFAULT '{}',
 expression_key text REFERENCES public.help_buddy_expression_catalog(expression_key) ON UPDATE CASCADE ON DELETE SET NULL,
 response_strategy text NOT NULL,requires_admin_review boolean NOT NULL DEFAULT false,
 enabled boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','retired')),
 sort_order integer NOT NULL DEFAULT 100,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.help_buddy_personality_blends(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),blend_key text NOT NULL UNIQUE,name text NOT NULL,
 description text NOT NULL DEFAULT '',personality_weights jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(personality_weights)='object'),
 context_tags text[] NOT NULL DEFAULT '{}',user_selectable boolean NOT NULL DEFAULT true,
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','retired')),
 sort_order integer NOT NULL DEFAULT 100,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.help_buddy_personality_preferences(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_type text NOT NULL CHECK(scope_type IN('user','organization')),
 profile_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
 organization_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE,
 personality_key text NOT NULL REFERENCES public.assistant_personality_presets(preset_key) ON UPDATE CASCADE ON DELETE RESTRICT,
 intensity smallint NOT NULL DEFAULT 50 CHECK(intensity BETWEEN 0 AND 100),enabled boolean NOT NULL DEFAULT true,
 priority smallint NOT NULL DEFAULT 100,created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
 updated_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK((scope_type='user' AND profile_id IS NOT NULL AND organization_id IS NULL)
 OR (scope_type='organization' AND profile_id IS NULL AND organization_id IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS help_buddy_personality_preferences_user_uq
 ON public.help_buddy_personality_preferences(profile_id,personality_key) WHERE scope_type='user';
CREATE UNIQUE INDEX IF NOT EXISTS help_buddy_personality_preferences_org_uq
 ON public.help_buddy_personality_preferences(organization_id,personality_key) WHERE scope_type='organization';
CREATE TABLE IF NOT EXISTS public.help_buddy_behavior_test_cases(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_key text NOT NULL UNIQUE,name text NOT NULL,
 sample_input text NOT NULL,expected_personality_keys text[] NOT NULL DEFAULT '{}',
 expected_expression_key text REFERENCES public.help_buddy_expression_catalog(expression_key) ON UPDATE CASCADE ON DELETE SET NULL,
 expected_severity smallint NOT NULL DEFAULT 1 CHECK(expected_severity BETWEEN 1 AND 5),
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','retired')),
 last_result text CHECK(last_result IN('pass','fail','not_run')),last_tested_at timestamptz,
 metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
