WITH category_seeds(category_order,category_key,category_name,names) AS (
 VALUES (1,'everyday_conversation','Everyday conversation',ARRAY['Neutral listening','Attentive listening','Natural speaking','Thoughtful response','Friendly acknowledgment','Head nod','Head tilt','Direct eye contact','Patient waiting','Ready-to-assist pose' ]::text[]),
(2,'happiness_excitement','Happiness and excitement',ARRAY['Gentle smile','Big smile','Laughing','Wide-eyed excitement','Cheerful wave','Thumbs-up','Clapping','Celebratory pose','Proud smile','Playful wink' ]::text[]),
(3,'thinking_intelligence','Thinking and intelligence',ARRAY['Deep concentration','Finger-on-chin thinking','Looking upward thoughtfully','Looking sideways while considering an idea','Arms crossed in thought','Reviewing information','Analyzing a problem','Connecting ideas','Lightbulb realization','Breakthrough discovery' ]::text[]),
(4,'teaching_explaining','Teaching and explaining',ARRAY['Explaining with one hand','Explaining with both hands','Pointing left','Pointing right','Pointing upward','Pointing downward','Presenting a lesson','Demonstrating instructions','Showing a helpful tip','Confident teaching pose' ]::text[]),
(5,'empathy_compassion','Empathy and compassion',ARRAY['Concerned expression','Sympathetic expression','Gentle reassuring smile','Listening with compassion','Apologetic expression','Comforting gesture','Encouraging expression','Understanding nod','Patient and caring expression','Supportive open-arm gesture' ]::text[]),
(6,'surprise_curiosity','Surprise and curiosity',ARRAY['Mild surprise','Complete surprise','Raised eyebrows','Confused expression','Scratching head','Puzzled expression','Wide-open eyes','Investigative curiosity','Questioning expression','Unexpected realization' ]::text[]),
(7,'professional_business','Professional and business',ARRAY['Formal greeting','Executive presentation','Professional confidence','Formal acknowledgment','Reviewing a business report','Examining a dashboard','Approving a task','Declining a request','Delivering a recommendation','Reporting successful completion' ]::text[]),
(8,'security_protection','Security and protection',ARRAY['Security alert expression','Serious warning expression','Protective stance','Security investigation pose','Suspicious activity detected','Stop-hand gesture','Access denied expression','Threat detected expression','Emergency response stance','Security clearance expression' ]::text[]),
(9,'humor_playfulness','Humor and playfulness',ARRAY['Mischievous grin','Playful wink','Laughing hard','Silly face','Funny shrug','Hands-on-hips pose','Playful pointing','Cheeky smile','Comical surprise','Playful celebration' ]::text[]),
(10,'frustration_disagreement','Frustration and disagreement',ARRAY['Mild frustration','Disapproving expression','Shaking head','Disappointed expression','Firm expression','Questioning with both hands','Correcting a mistake','Polite disagreement','Setting boundaries','Calming-down gesture' ]::text[]),
(11,'physical_interaction','Physical interaction and activities',ARRAY['Greeting with both hands','Waving goodbye','Giving directions','Inviting someone to participate','Presenting available options','Holding a tablet','Operating a computer','Making a phone call','Working at a desk','Giving a high-five' ]::text[]),
(12,'special_character_states','Special character states',ARRAY['Sleeping or resting','Waking up','Waiting for user input','Processing information','Celebrating an achievement','Reflective arms-crossed pose','Emergency standby','Maximum alert','Ready-for-action stance','Signature Help Buddy character pose' ]::text[])
), expression_seeds AS (
 SELECT row_number() OVER(ORDER BY category_order, item_order)::integer AS seq,
        category_key,category_name,name
 FROM category_seeds
 CROSS JOIN LATERAL unnest(names) WITH ORDINALITY AS items(name,item_order)
)
INSERT INTO public.help_buddy_expression_catalog
 (expression_key,category_key,category_name,name,description,emotion_tags,visual_spec,asset_status,status,sort_order)
SELECT 'ex'||lpad(seq::text,3,'0')||'_'||trim(both '_' from regexp_replace(lower(name),'[^a-z0-9]+','_','g')),
 category_key,category_name,name,
 'Help Buddy visual state: '||name||'. Maintain the approved character identity and use only when contextually appropriate.',
 CASE WHEN category_key='security_protection' THEN ARRAY['alert','protective','serious']
      WHEN category_key='empathy_compassion' THEN ARRAY['empathetic','supportive']
      WHEN category_key IN('happiness_excitement','humor_playfulness') THEN ARRAY['positive','friendly']
      WHEN category_key='frustration_disagreement' THEN ARRAY['firm','concerned']
      ELSE ARRAY['neutral','contextual'] END,
 jsonb_build_object('visual_state_id','EX'||lpad(seq::text,3,'0'),'distinct_asset_required',true,'maintain_character_identity',true),
 'awaiting_artwork','active',seq
FROM expression_seeds
ON CONFLICT(expression_key) DO UPDATE SET category_key=EXCLUDED.category_key,category_name=EXCLUDED.category_name,
 name=EXCLUDED.name,description=EXCLUDED.description,emotion_tags=EXCLUDED.emotion_tags,visual_spec=EXCLUDED.visual_spec,sort_order=EXCLUDED.sort_order;

INSERT INTO public.help_buddy_behavior_rules
 (rule_key,name,description,trigger_categories,severity_level,personality_keys,expression_key,response_strategy,requires_admin_review,enabled,status,sort_order)
VALUES ('emotional_cues','Emotional cues','Respond proportionately to emotional cues; do not diagnose or claim certainty.',ARRAY['sadness','frustration','confusion','excitement','disappointment'],1,ARRAY['empathetic','compassionate','sensitive'],'ex041_concerned_expression','supportive_acknowledgment',false,false,'draft',10),
('ordinary_profanity','Profanity','Do not mirror abusive language or over-escalate profanity.',ARRAY['profanity'],2,ARRAY['diplomatic','professional','friendly'],'ex099_setting_boundaries','calm_boundary_reminder',false,false,'draft',20),
('personal_insults','Personal insults','Address personal attacks with a respectful boundary and redirect.',ARRAY['insult','personal_attack'],3,ARRAY['diplomatic','serious','guardian'],'ex095_firm_expression','respectful_boundary_and_redirect',true,false,'draft',30),
('harassment','Harassment','Recognize targeted harassment and prioritize the affected person''s safety.',ARRAY['harassment','targeted_abuse'],3,ARRAY['diplomatic','protective','guardian'],'ex073_protective_stance','support_affected_user_and_offer_report_path',true,false,'draft',40),
('bullying','Bullying','Recognize repeated intimidation and follow organizational policy.',ARRAY['bullying','repeated_intimidation'],3,ARRAY['protective','diplomatic','serious'],'ex073_protective_stance','document_and_route_for_review',true,false,'draft',50),
('inappropriate_content','Inappropriate content','Set a clear boundary around sexual or otherwise disallowed content.',ARRAY['sexual_content','explicit_content'],3,ARRAY['professional','serious','guardian'],'ex099_setting_boundaries','policy_boundary_and_redirect',true,false,'draft',60),
('conflict_resolution','Conflict resolution','De-escalate disagreement, summarize points fairly, and propose next steps.',ARRAY['conflict','disagreement'],2,ARRAY['diplomatic','empathetic','cooperative'],'ex098_polite_disagreement','deescalate_and_summarize',false,false,'draft',70),
('suspicious_activity','Suspicious activity','Flag suspicious activity for authorized review without unsupported accusations.',ARRAY['suspicious_activity','anomalous_request'],4,ARRAY['detective','protective','serious'],'ex075_suspicious_activity_detected','security_review_notice',true,false,'draft',80),
('privacy_exposure','Privacy exposure','Prevent unnecessary disclosure of personal or confidential information.',ARRAY['privacy_exposure','confidential_data'],4,ARRAY['guardian','protective','professional'],'ex071_security_alert_expression','privacy_protection_and_restrict_disclosure',true,false,'draft',90),
('credential_request','Credential request','Never request or expose passwords, tokens, or private keys in conversation.',ARRAY['credential_request','secret_exposure'],5,ARRAY['guardian','serious','protective'],'ex078_threat_detected_expression','refuse_secret_handling_and_route_securely',true,false,'draft',100),
('unauthorized_access','Unauthorized access','Do not assist bypassing access controls; direct users to approved access workflows.',ARRAY['unauthorized_access','permission_bypass'],5,ARRAY['guardian','serious','professional'],'ex077_access_denied_expression','deny_and_direct_to_access_request',true,false,'draft',110),
('security_incident','Security incident','Use a serious security posture and notify authorized responders where configured.',ARRAY['security_incident','confirmed_threat'],5,ARRAY['serious','protective','guardian'],'ex079_emergency_response_stance','invoke_authorized_incident_escalation',true,false,'draft',120),
('emergency','Emergency','Provide concise safety-first guidance and invoke configured emergency procedures.',ARRAY['emergency','immediate_harm'],5,ARRAY['serious','compassionate','guardian'],'ex117_emergency_standby','emergency_protocol_and_human_handoff',true,false,'draft',130),
('uncertainty','Unverified information','Acknowledge uncertainty, seek approved sources, and never fabricate an answer.',ARRAY['unknown_answer','low_confidence'],1,ARRAY['humble','intelligent','cautious'],'ex004_thoughtful_response','state_uncertainty_and_retrieve_verified_source',false,false,'draft',140),
('repeated_behavior','Repeated inappropriate behavior','Consider pattern and context before escalating repeated behavior.',ARRAY['repeated_policy_violation'],3,ARRAY['serious','diplomatic','guardian'],'ex095_firm_expression','proportionate_policy_reminder_and_review',true,false,'draft',150)
ON CONFLICT(rule_key) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,trigger_categories=EXCLUDED.trigger_categories,
 severity_level=EXCLUDED.severity_level,personality_keys=EXCLUDED.personality_keys,expression_key=EXCLUDED.expression_key,
 response_strategy=EXCLUDED.response_strategy,requires_admin_review=EXCLUDED.requires_admin_review,sort_order=EXCLUDED.sort_order;
