ALTER TABLE public.help_buddy_expression_catalog ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_buddy_behavior_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_buddy_personality_blends ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_buddy_personality_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_buddy_behavior_test_cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.assistant_personality_presets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users read active Help Buddy expressions" ON public.help_buddy_expression_catalog FOR SELECT TO authenticated USING(status='active');
CREATE POLICY "Global admins manage Help Buddy expressions" ON public.help_buddy_expression_catalog FOR ALL TO authenticated USING(private.is_global_admin()) WITH CHECK(private.is_global_admin());
CREATE POLICY "Authenticated users read published Help Buddy behavior rules" ON public.help_buddy_behavior_rules FOR SELECT TO authenticated USING(enabled=true AND status='published');
CREATE POLICY "Global admins manage Help Buddy behavior rules" ON public.help_buddy_behavior_rules FOR ALL TO authenticated USING(private.is_global_admin()) WITH CHECK(private.is_global_admin());
CREATE POLICY "Authenticated users read active Help Buddy personality blends" ON public.help_buddy_personality_blends FOR SELECT TO authenticated USING(status='active');
CREATE POLICY "Global admins manage Help Buddy personality blends" ON public.help_buddy_personality_blends FOR ALL TO authenticated USING(private.is_global_admin()) WITH CHECK(private.is_global_admin());
CREATE POLICY "Users manage own Help Buddy personality preferences" ON public.help_buddy_personality_preferences FOR ALL TO authenticated
 USING((scope_type='user' AND profile_id=(SELECT auth.uid()))
 OR (scope_type='organization' AND organization_id IN(SELECT p.organization_id FROM public.profiles p WHERE p.id=(SELECT auth.uid())))
 OR private.is_global_admin())
 WITH CHECK((scope_type='user' AND profile_id=(SELECT auth.uid()) AND organization_id IS NULL)
 OR (scope_type='organization' AND profile_id IS NULL AND (organization_id IN(SELECT p.organization_id FROM public.profiles p WHERE p.id=(SELECT auth.uid())) OR private.is_global_admin()))
 OR private.is_global_admin());
CREATE POLICY "Global admins manage Help Buddy behavior test cases" ON public.help_buddy_behavior_test_cases FOR ALL TO authenticated USING(private.is_global_admin()) WITH CHECK(private.is_global_admin());
CREATE POLICY "Global admins manage assistant personality presets" ON public.assistant_personality_presets FOR ALL TO authenticated USING(private.is_global_admin()) WITH CHECK(private.is_global_admin());
REVOKE ALL ON public.help_buddy_expression_catalog,public.help_buddy_behavior_rules,public.help_buddy_personality_blends,
 public.help_buddy_personality_preferences,public.help_buddy_behavior_test_cases FROM anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.help_buddy_expression_catalog,public.help_buddy_behavior_rules,public.help_buddy_personality_blends,
 public.help_buddy_personality_preferences,public.help_buddy_behavior_test_cases TO authenticated;
GRANT ALL ON public.help_buddy_expression_catalog,public.help_buddy_behavior_rules,public.help_buddy_personality_blends,
 public.help_buddy_personality_preferences,public.help_buddy_behavior_test_cases TO service_role;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.assistant_personality_presets TO authenticated;
CREATE INDEX IF NOT EXISTS help_buddy_expression_category_status_idx ON public.help_buddy_expression_catalog(category_key,status,sort_order);
CREATE INDEX IF NOT EXISTS help_buddy_behavior_rules_active_idx ON public.help_buddy_behavior_rules(enabled,status,severity_level);
CREATE INDEX IF NOT EXISTS help_buddy_behavior_test_cases_status_idx ON public.help_buddy_behavior_test_cases(status,case_key);
